  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local alias with explicit restrict to help the optimizer reason about
     the absence of aliasing involving A. */
  DATA_TYPE (*restrict a)[n] = A;

  /* Auxiliary 1D buffer that stores 1 / A[j][j] after row j is completed.
     This replaces O(N^2) divisions in the original kernel with O(N^2)
     multiplications and only O(N) divisions overall. The extra memory
     usage is O(N), which is negligible compared to the O(N^2) matrix. */
  DATA_TYPE inv_diag[n];

#pragma scop
  /* In-place left-looking Cholesky factorization.
     Original algorithm (for each row i):
       for j < i:
         for k < j:    A[i][j] -= A[i][k] * A[j][k];
         A[i][j] /= A[j][j];
       for k < i:      A[i][i] -= A[i][k] * A[i][k];
       A[i][i] = sqrt(A[i][i]);

     We rewrite the inner updates as explicit dot products accumulated in
     local scalars (sum, sum2). This:
       - reduces memory traffic on A[i][j] / A[i][i],
       - exposes clean reduction loops in k that are easy to vectorize,
       - allows us to use inv_diag[j] instead of dividing by A[j][j]
         for every off-diagonal element. */

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *restrict Ai = a[i];

      /* Off-diagonal elements in row i: columns j = 0 .. i-1. */
      for (j = 0; j < i; j++)
        {
          DATA_TYPE *restrict Aj = a[j];
          DATA_TYPE sum = (DATA_TYPE)0;

          /* Compute dot product sum_{k=0}^{j-1} A[i][k] * A[j][k].
             This is a simple reduction over k and is friendly to
             automatic SIMD vectorization. */
          for (k = 0; k < j; k++)
            sum += Ai[k] * Aj[k];

          /* Original:
               for (k = 0; k < j; k++) A[i][j] -= A[i][k] * A[j][k];
               A[i][j] /= A[j][j];

             Equivalent (modulo floating-point reassociation):
               A[i][j] = (A[i][j] - sum) / A[j][j];

             Here we use the precomputed reciprocal inv_diag[j] = 1/A[j][j]
             to replace the division by a multiplication. */
          Ai[j] = (Ai[j] - sum) * inv_diag[j];
        }

      /* Diagonal element in row i. */
      {
        DATA_TYPE sum2 = (DATA_TYPE)0;

        /* Compute sum_{k=0}^{i-1} A[i][k]^2. */
        for (k = 0; k < i; k++)
          {
            DATA_TYPE aik = Ai[k];
            sum2 += aik * aik;
          }

        /* Original:
             for (k = 0; k < i; k++) A[i][i] -= A[i][k] * A[i][k];
             A[i][i] = sqrt(A[i][i]);

           Equivalent:
             A[i][i] = sqrt(A[i][i] - sum2); */
        Ai[i] = SQRT_FUN(Ai[i] - sum2);
      }

      /* Precompute reciprocal of the diagonal for use in later rows.
         For all future rows i' > i, column j = i uses inv_diag[i]
         instead of dividing by A[i][i] every time. */
      inv_diag[i] = (DATA_TYPE)1.0 / Ai[i];
    }
#pragma endscop

}


