   - Use an auxiliary array inv_diag[i] = 1 / A[i][i] to replace O(N^2)
     divisions by multiplications, keeping only O(N) divisions.
   - Express inner products as explicit scalar reductions, improving
     cache use and enabling SIMD vectorization.
   - Add a simple blocking of the outer i-loop to improve locality
     when N is large.
   - Use compiler hints (ivdep + unroll) on the innermost reductions
     to encourage vectorization and unrolling.
*/
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Precomputed reciprocals of diagonal entries:
     inv_diag[i] = 1 / A[i][i] after row i is finished.
     Size is O(n), which is negligible compared to the O(n^2) matrix. */
  DATA_TYPE inv_diag[n];

  /* Tile size for the outer i-loop.
     Chosen as a moderate value that tends to fit several rows of A
     and their working set in cache. */
  const int block_i = 64;

#pragma scop
  /* Block outer loop over rows to improve cache locality. */
  for (int I = 0; I < _PB_N; I += block_i)
  {
    int i_end = I + block_i;
    if (i_end > _PB_N)
      i_end = _PB_N;

    /* Process rows i within the current tile. The global order of i
       (0, 1, 2, ..., N-1) is preserved across tiles, so all original
       data dependencies remain intact. */
    for (i = I; i < i_end; ++i)
    {
      DATA_TYPE *Ai = A[i];

      /* Off-diagonal elements in row i: columns 0 .. i-1.
         Original code:
           for (j = 0; j < i; ++j) {
             for (k = 0; k < j; ++k)
               A[i][j] -= A[i][k] * A[j][k];
             A[i][j] /= A[j][j];
           }

         We compute the same value as:
           sum = Σ_{k=0}^{j-1} A[i][k] * A[j][k];
           A[i][j] = (A[i][j] - sum) / A[j][j];

         but we:
           - use a scalar 'sum' accumulator,
           - replace the division by multiplication with inv_diag[j]. */
      for (j = 0; j < i; ++j)
      {
        DATA_TYPE *Aj = A[j];
        DATA_TYPE sum = 0;

        /* Dot product of row i and row j on columns 0..j-1.

           There are no loop-carried dependencies along k; this
           loop is a pure reduction into 'sum', so it can be
           safely vectorized. */
#pragma GCC ivdep
#pragma GCC unroll 4
        for (k = 0; k < j; ++k)
        {
          sum += Ai[k] * Aj[k];
        }

        /* A[i][j] = (A[i][j] - sum) / A[j][j]
           implemented as a multiply with precomputed reciprocal:

             inv_diag[j] = 1 / A[j][j]   (set when row j was finished) */
        Ai[j] = (Ai[j] - sum) * inv_diag[j];
      }

      /* Diagonal element in row i.

         Original code:
           for (k = 0; k < i; ++k)
             A[i][i] -= A[i][k] * A[i][k];
           A[i][i] = SQRT_FUN(A[i][i]);

         We equivalently compute:
           sum = Σ_{k=0}^{i-1} A[i][k]^2;
           A[i][i] = SQRT_FUN(A[i][i] - sum); */
      DATA_TYPE sum = 0;

#pragma GCC ivdep
#pragma GCC unroll 4
      for (k = 0; k < i; ++k)
      {
        DATA_TYPE aik = Ai[k];
        sum += aik * aik;
      }

      Ai[i] = SQRT_FUN(Ai[i] - sum);

      /* Precompute 1 / A[i][i] for later rows.
         Subsequent off-diagonal updates with column j = i will use this
         instead of performing a division for each A[*, i]. */
      inv_diag[i] = (DATA_TYPE)1.0 / Ai[i];
    }
  }
#pragma endscop

}


