/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* ------------------------------------------------------------------
   * Optimization overview
   *
   * 1) We keep the original left-looking Cholesky algorithm and loop
   *    ordering, so all true data dependencies are preserved.
   *
   * 2) We introduce a small 1D auxiliary array inv_diag[] that stores
   *    1 / A[j][j] after each diagonal is computed. This replaces the
   *    O(N^2) divisions "A[i][j] /= A[j][j]" with cheaper
   *    multiplications "A[i][j] *= inv_diag[j]". Only O(N) divisions
   *    remain, one per row.
   *
   * 3) For the inner products over k (dot products), we:
   *       - accumulate into a scalar 'sum' in registers instead of
   *         repeatedly updating A[i][j] / A[i][i] in memory,
   *       - apply simple tiling over k for better cache behavior,
   *       - manually unroll by 4 to provide ILP and help auto-SIMD.
   *
   *    These transformations change only the order of mathematically
   *    associative operations; the algorithm and data dependencies
   *    remain equivalent to the original code.
   * ------------------------------------------------------------------ */

  /* Small auxiliary buffer: reciprocal of diagonal entries.
   * Size is O(N) and thus negligible compared to the N×N matrix. */
  DATA_TYPE inv_diag[_PB_N];

  /* Tile size for the reduction dimension k. This is a compile-time
   * constant chosen to fit well in L1/L2 cache on modern x64 cores. */
  const int TILE_K = 64;

#pragma scop
  for (i = 0; i < _PB_N; i++)
  {
    /* Pointer to the current row i to improve spatial locality and let
     * the compiler generate better code (possibly with SIMD). */
    DATA_TYPE *Ai = A[i];

    /* ---------------- Off-diagonal elements in row i ----------------
     * Original:
     *   for (j = 0; j < i; j++) {
     *     for (k = 0; k < j; k++)
     *       A[i][j] -= A[i][k] * A[j][k];
     *     A[i][j] /= A[j][j];
     *   }
     *
     * We compute the same quantity as:
     *   dot = sum_{k < j} A[i][k] * A[j][k]
     *   A[i][j] = (A[i][j] - dot) / A[j][j]
     * and use inv_diag[j] = 1.0 / A[j][j] to turn the division into
     * a multiplication.
     */
    for (j = 0; j < i; j++)
    {
      DATA_TYPE *Aj = A[j];
      DATA_TYPE sum = 0;

      /* Block the reduction over k and manually unroll by 4 inside each
       * block to expose more instruction-level parallelism and help the
       * compiler vectorize on the k-dimension. */
      for (int kk = 0; kk < j; kk += TILE_K)
      {
        int kend = kk + TILE_K;
        if (kend > j)
          kend = j;

        int k = kk;

        /* Unrolled inner loop: process 4 elements of the dot product
         * per iteration when possible. */
        for (; k + 3 < kend; k += 4)
        {
          DATA_TYPE a0 = Ai[k];
          DATA_TYPE a1 = Ai[k+1];
          DATA_TYPE a2 = Ai[k+2];
          DATA_TYPE a3 = Ai[k+3];

          DATA_TYPE b0 = Aj[k];
          DATA_TYPE b1 = Aj[k+1];
          DATA_TYPE b2 = Aj[k+2];
          DATA_TYPE b3 = Aj[k+3];

          sum += a0 * b0 + a1 * b1 + a2 * b2 + a3 * b3;
        }

        /* Remainder of the tile (0–3 iterations). */
        for (; k < kend; k++)
        {
          sum += Ai[k] * Aj[k];
        }
      }

      /* Final off-diagonal update using precomputed reciprocal of A[j][j]. */
      Ai[j] = (Ai[j] - sum) * inv_diag[j];
    }

    /* ----------------- Diagonal element A[i][i] --------------------
     * Original:
     *   for (k = 0; k < i; k++)
     *     A[i][i] -= A[i][k] * A[i][k];
     *   A[i][i] = SQRT_FUN(A[i][i]);
     *
     * We instead compute:
     *   sum = ∑_{k < i} A[i][k]^2
     *   A[i][i] = sqrt(A[i][i] - sum)
     */
    {
      DATA_TYPE sum = 0;

      for (int kk = 0; kk < i; kk += TILE_K)
      {
        int kend = kk + TILE_K;
        if (kend > i)
          kend = i;

        int k = kk;

        /* Unrolled inner loop over k for the diagonal dot product. */
        for (; k + 3 < kend; k += 4)
        {
          DATA_TYPE a0 = Ai[k];
          DATA_TYPE a1 = Ai[k+1];
          DATA_TYPE a2 = Ai[k+2];
          DATA_TYPE a3 = Ai[k+3];

          sum += a0 * a0 + a1 * a1 + a2 * a2 + a3 * a3;
        }

        for (; k < kend; k++)
        {
          DATA_TYPE aik = Ai[k];
          sum += aik * aik;
        }
      }

      Ai[i] = SQRT_FUN(Ai[i] - sum);

      /* Store 1 / A[i][i] for use in later rows. This reduces the
       * number of divisions in the overall factorization from O(N^2)
       * to O(N). */
      inv_diag[i] = (DATA_TYPE)1.0 / Ai[i];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
