/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (versus the original kernel):
   - Arithmetic:
       * Introduce a 1D auxiliary array inv_diag[i] = 1 / A[i][i].
         This turns O(N^2) divisions (one per A[i][j], j < i) into
         O(N^2) multiplications plus only O(N) divisions, which is
         significantly faster on modern CPUs.
       * Express the inner k-loops as explicit dot products accumulated
         in scalars. This is more amenable to auto-vectorization than
         repeatedly updating A[i][j] / A[i][i] in memory.
   - Locality and ILP:
       * Use row pointers (Ai, Aj) to improve alias analysis and enable
         contiguous accesses along k.
       * Manually unroll the reduction loops by a factor of 4 to expose
         instruction-level parallelism and help the compiler generate
         efficient SIMD code.
   The overall mathematical algorithm remains the standard left-looking
   in-place Cholesky factorization, producing the same L such that
   A ≈ L·Lᵀ (up to usual FP round-off differences).
*/
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Local buffer holding 1 / A[i][i] once row i is completed.
     Size is O(N) and negligible compared to the O(N^2) matrix A. */
  int n_pb = _PB_N;
  DATA_TYPE inv_diag[_PB_N];

#pragma scop
  for (i = 0; i < n_pb; i++) {
    /* Pointer to the current row; helps the compiler see that accesses
       along k are contiguous and often enables better vectorization. */
    DATA_TYPE * __restrict Ai = A[i];

    /* Off-diagonal elements: columns j = 0 .. i-1. */
    for (j = 0; j < i; j++) {
      DATA_TYPE * __restrict Aj = A[j];

      /* Compute dot_ij = sum_{k=0}^{j-1} Ai[k] * Aj[k] using a
         partially unrolled reduction. */
      DATA_TYPE sum0 = (DATA_TYPE)0;
      DATA_TYPE sum1 = (DATA_TYPE)0;
      DATA_TYPE sum2 = (DATA_TYPE)0;
      DATA_TYPE sum3 = (DATA_TYPE)0;

      int k = 0;

      /* Unrolled main loop: process 4 elements of the dot product per
         iteration to increase ILP and make vectorization easier. */
#pragma GCC ivdep
      for (; k + 3 < j; k += 4) {
        sum0 += Ai[k]     * Aj[k];
        sum1 += Ai[k + 1] * Aj[k + 1];
        sum2 += Ai[k + 2] * Aj[k + 2];
        sum3 += Ai[k + 3] * Aj[k + 3];
      }

      /* Remainder loop for j not divisible by 4. */
      for (; k < j; k++) {
        sum0 += Ai[k] * Aj[k];
      }

      DATA_TYPE dot_ij = ((sum0 + sum1) + (sum2 + sum3));

      /* Original code:
           for (k = 0; k < j; k++)
             A[i][j] -= A[i][k] * A[j][k];
           A[i][j] /= A[j][j];

         With inv_diag[j] = 1 / A[j][j] (computed when row j was
         finished), this is algebraically:
           A[i][j] = (A[i][j] - dot_ij) * inv_diag[j];
      */
      Ai[j] = (Ai[j] - dot_ij) * inv_diag[j];
    }

    /* Diagonal element A[i][i]. We compute:
         dot_ii = sum_{k=0}^{i-1} Ai[k]^2
         A[i][i] = sqrt( A[i][i] - dot_ii );
       using the same unrolled reduction scheme. */
    DATA_TYPE sum0 = (DATA_TYPE)0;
    DATA_TYPE sum1 = (DATA_TYPE)0;
    DATA_TYPE sum2 = (DATA_TYPE)0;
    DATA_TYPE sum3 = (DATA_TYPE)0;
    int k = 0;

