      DATA_TYPE a1 = Ai[k + 1];
      DATA_TYPE a2 = Ai[k + 2];
      DATA_TYPE a3 = Ai[k + 3];

      sum0 += a0 * a0;
      sum1 += a1 * a1;
      sum2 += a2 * a2;
      sum3 += a3 * a3;
