    DATA_TYPE dot_ii = ((sum0 + sum1) + (sum2 + sum3));

    /* Finalize the diagonal and store its reciprocal. */
    DATA_TYPE diag = SQRT_FUN(Ai[i] - dot_ii);
    Ai[i] = diag;
    inv_diag[i] = (DATA_TYPE)1.0 / diag;
  }
#pragma endscop

